        for id in self.proposal_ids(owner) {
            self.accept(&id, cx).ok();
        }
    }

    fn reject_all(&mut self, owner: Option<&str>, cx: &mut Context<Self>) {
        for id in self.proposal_ids(owner) {
            self.reject(&id, cx);
        }
